  claimGjcIntent(intentId: string, worker: string, now = timestamp(), leaseMs = 60_000): Record<string, unknown> | null {
    if (!worker || leaseMs < 1) throw new JarvisError("GJC_LEASE_INVALID"); return this.atomic(() => { this.db.prepare("UPDATE gjc_intents SET state='pending',lease_owner=NULL,lease_expires_at=NULL WHERE state='claimed' AND lease_expires_at<=?").run(now); const row = this.db.prepare("SELECT * FROM gjc_intents WHERE intent_id=?").get(intentId) as Row | undefined; if (!row) throw new JarvisError("GJC_INTENT_NOT_FOUND"); if (row.state !== "pending") return null; const fence = Number(row.lease_fence) + 1; const expires = new Date(Date.parse(now) + leaseMs).toISOString(); const changed = this.db.prepare("UPDATE gjc_intents SET state='claimed',attempts=attempts+1,lease_owner=?,lease_fence=?,lease_expires_at=? WHERE intent_id=? AND state='pending'").run(worker, fence, expires, intentId); if (changed.changes !== 1) return null; this.db.prepare("INSERT INTO gjc_intent_events(intent_id,event_type,payload_json,created_at) VALUES(?,?,?,?)").run(intentId, "claimed", json({ worker, fence }), now); return { ...row, lease_fence: fence, lease_expires_at: expires }; });
  }
  settleGjcIntent(intentId: string, fence: number, result: { status: "accepted" | "completed" | "failed" | "uncertain"; receipt?: unknown; failure_code?: string }, now = timestamp()): void {
    const valid = new Set(["accepted", "completed", "failed", "uncertain"]); if (!valid.has(result.status)) throw new JarvisError("GJC_STATUS_INVALID"); this.atomic(() => { const row = this.db.prepare("SELECT * FROM gjc_intents WHERE intent_id=?").get(intentId) as Row | undefined; if (!row || row.state !== "claimed" || Number(row.lease_fence) !== fence) throw new JarvisError("GJC_STALE_LEASE"); const receipt = result.receipt === undefined ? null : json(result.receipt); const acceptedAt = result.status === "accepted" || result.status === "completed" ? now : null; const completedAt = result.status === "completed" || result.status === "failed" ? now : null; this.db.prepare("UPDATE gjc_intents SET state=?,receipt_json=COALESCE(?,receipt_json),accepted_at=COALESCE(?,accepted_at),completed_at=COALESCE(?,completed_at),failure_code=?,lease_owner=NULL,lease_expires_at=NULL WHERE intent_id=? AND state='claimed' AND lease_fence=?").run(result.status, receipt, acceptedAt, completedAt, result.failure_code ?? null, intentId, fence); this.db.prepare("INSERT INTO gjc_intent_events(intent_id,event_type,payload_json,created_at) VALUES(?,?,?,?)").run(intentId, result.status, json({ receipt: result.receipt ?? null, failure_code: result.failure_code ?? null }), now); if (row.kind === "dispatch" && (result.status === "accepted" || result.status === "completed")) { const reply = result.receipt as Record<string, unknown> | undefined; const config = this.gjcConfig(); if (!reply || !config || reply.session_id !== config.session_id || typeof reply.turn_id !== "string" || !reply.turn_id) throw new JarvisError("GJC_DISPATCH_RECEIPT_INVALID"); this.db.prepare("INSERT INTO gjc_dispatch_receipts(intent_id,session_id,turn_id,receipt_json,accepted_at) VALUES(?,?,?,?,?)").run(intentId, reply.session_id, reply.turn_id, receipt, now); const syncKey = deterministic("gjc-reconcile", `${intentId}:${reply.turn_id}`); const syncId = deterministic("gjc", syncKey); const payload = json({ session_id: config.session_id, turn_id: reply.turn_id }); this.db.prepare("INSERT INTO gjc_intents(intent_id,continuation_id,kind,payload_json,payload_digest,idempotency_key,state,created_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(idempotency_key) DO NOTHING").run(syncId, row.continuation_id, "sync", payload, sha(payload), syncKey, "pending", now); this.db.prepare("INSERT INTO gjc_intent_events(intent_id,event_type,payload_json,created_at) SELECT ?,?,?,? WHERE changes()=1").run(syncId, "created", json({ kind: "sync", source_intent_id: intentId }), now); } });
  }
  bindGjcQuestion(intentId: string, questionId: string, snapshot: unknown, now = timestamp()): void { const snapshot_json = json(snapshot); const snapshot_digest = sha(snapshot_json); this.atomic(() => { const prior = this.db.prepare("SELECT intent_id,snapshot_digest FROM gjc_questions WHERE question_id=?").get(questionId) as Row | undefined; if (prior) { if (prior.intent_id !== intentId || prior.snapshot_digest !== snapshot_digest) throw new JarvisError("GJC_QUESTION_BINDING_CONFLICT"); return; } this.db.prepare("INSERT INTO gjc_questions(question_id,intent_id,snapshot_json,snapshot_digest,state,created_at) VALUES(?,?,?,?,?,?)").run(questionId, intentId, snapshot_json, snapshot_digest, "open", now); }); }
  createGjcQuestionAnswerIntent(questionId: string, input: Record<string, unknown>, idempotencyKey: string, now = timestamp()): string {
    const config = this.gjcConfig(); if (!config?.operational || !idempotencyKey) throw new JarvisError("GJC_ANSWER_NOT_AUTHORIZED"); const keys = Object.keys(input).sort(); if (keys.join(",") !== "answer,answer_binding,session_id,turn_id" || input.session_id !== config.session_id || typeof input.turn_id !== "string" || !input.turn_id || typeof input.answer_binding !== "object" || input.answer_binding === null || Array.isArray(input.answer_binding)) throw new JarvisError("GJC_ANSWER_SCHEMA_INVALID");
    const question = this.db.prepare("SELECT snapshot_json,state FROM gjc_questions WHERE question_id=?").get(questionId) as Row | undefined; if (!question || question.state !== "open") throw new JarvisError("GJC_QUESTION_NOT_OPEN"); let snapshot: Record<string, unknown>; try { snapshot = JSON.parse(String(question.snapshot_json)) as Record<string, unknown>; } catch { throw new JarvisError("GJC_QUESTION_BINDING_CONFLICT"); }
    if (snapshot.question_id !== questionId || snapshot.session_id !== input.session_id || snapshot.turn_id !== input.turn_id) throw new JarvisError("GJC_QUESTION_BINDING_CONFLICT"); return this.createGjcIntent("answer", { session_id: input.session_id, turn_id: input.turn_id, question_id: questionId, answer_binding: input.answer_binding, answer: input.answer }, idempotencyKey, undefined, now);
  }
  answerGjcQuestion(questionId: string, answer: unknown, idempotencyKey: string, receipt?: unknown, now = timestamp()): void { const answer_json = json(answer); const answer_digest = sha(answer_json); this.atomic(() => { const question = this.db.prepare("SELECT state FROM gjc_questions WHERE question_id=?").get(questionId) as Row | undefined; if (!question) throw new JarvisError("GJC_QUESTION_NOT_FOUND"); const prior = this.db.prepare("SELECT idempotency_key,answer_digest FROM gjc_question_answers WHERE question_id=?").get(questionId) as Row | undefined; if (prior) { if (prior.idempotency_key !== idempotencyKey || prior.answer_digest !== answer_digest) throw new JarvisError("GJC_ANSWER_REPLAY_CONFLICT"); return; } if (question.state !== "open") throw new JarvisError("GJC_QUESTION_NOT_OPEN"); this.db.prepare("INSERT INTO gjc_question_answers(question_id,idempotency_key,answer_json,answer_digest,receipt_json,created_at) VALUES(?,?,?,?,?,?)").run(questionId, idempotencyKey, answer_json, answer_digest, receipt === undefined ? null : json(receipt), now); this.db.prepare("UPDATE gjc_questions SET state='answered',answered_at=? WHERE question_id=? AND state='open'").run(now, questionId); }); }
  persistObservation(value: unknown, now = timestamp()): StoredObservation { return this.personalContext.persistObservation(value, now); }
  persistContextSnapshot(value: ContextPersistenceInput, now = timestamp()): StoredContext {
    return this.personalContext.persistContext(value, now);
  }
